import Layout from "@/components/Layout";
import { useLessons } from "@/hooks/use-lessons";
import { useChallenges } from "@/hooks/use-challenges";
import { useProgress } from "@/hooks/use-progress";
import { Link } from "wouter";
import { Shield, ArrowRight, Flag, BookOpen, CheckCircle2, Award } from "lucide-react";
import { motion } from "framer-motion";
import { GlitchHeading } from "@/components/GlitchHeading";
import { Button } from "@/components/ui/button";

const POINTS = {
  lessonComplete: 100,
  challengeEasy: 200,
  challengeMedium: 350,
  challengeHard: 500,
};

function calculateScore(completedLessons: number, solvedChallenges: Array<{ difficulty: string }>) {
  let score = completedLessons * POINTS.lessonComplete;
  for (const ch of solvedChallenges) {
    switch (ch.difficulty.toLowerCase()) {
      case "easy":     score += POINTS.challengeEasy; break;
      case "medium":   score += POINTS.challengeMedium; break;
      case "hard":
      case "advanced": score += POINTS.challengeHard; break;
      default:         score += POINTS.challengeMedium;
    }
  }
  return score;
}

export default function Home() {
  const { data: lessons }    = useLessons();
  const { data: challenges } = useChallenges();
  const { data: progress }   = useProgress();

  const completedLessons    = (progress || []).filter(p => p.resourceType === "lesson").length;
  const solvedChallengeIds  = new Set((progress || []).filter(p => p.resourceType === "challenge").map(p => p.resourceId));
  const capturedFlags       = solvedChallengeIds.size;
  const totalLessons        = lessons?.length || 0;
  const totalChallenges     = challenges?.length || 0;
  const solvedChallenges    = (challenges || []).filter(c => solvedChallengeIds.has(c.id));
  const score               = calculateScore(completedLessons, solvedChallenges);
  const maxScore            = totalLessons * POINTS.lessonComplete +
    (challenges || []).reduce((sum, ch) => {
      switch (ch.difficulty.toLowerCase()) {
        case "easy":     return sum + POINTS.challengeEasy;
        case "medium":   return sum + POINTS.challengeMedium;
        case "hard":
        case "advanced": return sum + POINTS.challengeHard;
        default:         return sum + POINTS.challengeMedium;
      }
    }, 0);

  return (
    <Layout>
      {/* Hero */}
      <section className="relative py-12 md:py-24 overflow-hidden">
        <div className="flex flex-col items-center text-center max-w-4xl mx-auto space-y-8 z-10 relative">
          <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-primary/10 border border-primary/20 text-primary text-xs font-mono font-medium tracking-wide">
            <span className="relative flex h-2 w-2">
              <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-primary opacity-75" />
              <span className="relative inline-flex rounded-full h-2 w-2 bg-primary" />
            </span>
            SYSTEM ONLINE // READY FOR INSTRUCTION
          </div>

          <GlitchHeading
            text="SECURITY OPERATIONS ACADEMY"
            className="text-4xl md:text-6xl lg:text-7xl font-display font-bold tracking-tight bg-gradient-to-r from-white via-gray-200 to-gray-500 bg-clip-text text-transparent"
          />

          <p className="text-xl text-muted-foreground max-w-2xl leading-relaxed">
            An interactive training platform for security professionals. Master offensive and defensive techniques through guided learning paths and hands-on CTF challenges.
          </p>

          {/* Mascots */}
          <div className="flex items-end justify-center gap-8 my-2">
            <div className="flex flex-col items-center gap-1 opacity-70 hover:opacity-90 transition-opacity">
              <img src="data:image/png;base64," alt="Quarantine Blob" style={{height:"140px",width:"auto",filter:"drop-shadow(0 0 20px rgba(226,75,74,0.3))"}} />
              <span style={{fontFamily:"JetBrains Mono",fontSize:"9px",letterSpacing:"2px",color:"#e24b4a",opacity:0.7}}>QUARANTINE BLOB</span>
            </div>
            <div className="flex flex-col items-center gap-1 opacity-70 hover:opacity-90 transition-opacity">
              <img src="data:image/png;base64," alt="DroidGhost" style={{height:"140px",width:"auto",filter:"drop-shadow(0 0 20px rgba(34,197,94,0.3))"}} />
              <span style={{fontFamily:"JetBrains Mono",fontSize:"9px",letterSpacing:"2px",color:"#22c55e",opacity:0.7}}>DROIDGHOST</span>
            </div>
          </div>

          <div className="flex flex-col sm:flex-row gap-4 pt-4">
            <Link href="/learn">
              <Button size="lg">
                <Shield className="w-4 h-4 mr-2" />
                Browse Learning Paths
              </Button>
            </Link>
            <Link href="/learn">
              <Button variant="outline" size="lg">
                <Flag className="w-4 h-4 mr-2" />
                CTF Challenges
                <ArrowRight className="w-4 h-4 ml-2" />
              </Button>
            </Link>
          </div>
        </div>
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[800px] h-[800px] bg-primary/5 rounded-full blur-3xl -z-10" />
      </section>

      {/* Stats */}
      <section className="py-12">
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6 font-mono text-sm">
          <div className="bg-card border border-border p-6 rounded-lg">
            <div className="text-muted-foreground mb-2 flex items-center gap-2">
              <BookOpen className="w-4 h-4" /> MODULES
            </div>
            <div className="text-2xl font-bold text-primary">{completedLessons}/{totalLessons} COMPLETED</div>
            {totalLessons > 0 && (
              <div className="mt-2 h-1.5 bg-muted rounded-full overflow-hidden">
                <div className="h-full bg-primary rounded-full transition-all" style={{ width: `${(completedLessons / totalLessons) * 100}%` }} />
              </div>
            )}
          </div>
          <div className="bg-card border border-border p-6 rounded-lg">
            <div className="text-muted-foreground mb-2 flex items-center gap-2">
              <Flag className="w-4 h-4" /> FLAGS CAPTURED
            </div>
            <div className="text-2xl font-bold text-amber-500">{capturedFlags}/{totalChallenges} SOLVED</div>
            {totalChallenges > 0 && (
              <div className="mt-2 h-1.5 bg-muted rounded-full overflow-hidden">
                <div className="h-full bg-amber-500 rounded-full transition-all" style={{ width: `${(capturedFlags / totalChallenges) * 100}%` }} />
              </div>
            )}
          </div>
          <div className="bg-card border border-border p-6 rounded-lg">
            <div className="text-muted-foreground mb-2 flex items-center gap-2">
              <Award className="w-4 h-4" /> SCORE
            </div>
            <div className="text-2xl font-bold text-purple-400">{score.toLocaleString()} PTS</div>
            {maxScore > 0 && (
              <div className="mt-2 h-1.5 bg-muted rounded-full overflow-hidden">
                <div className="h-full bg-purple-400 rounded-full transition-all" style={{ width: `${(score / maxScore) * 100}%` }} />
              </div>
            )}
          </div>
          <div className="bg-card border border-border p-6 rounded-lg">
            <div className="text-muted-foreground mb-2 flex items-center gap-2">
              <CheckCircle2 className="w-4 h-4" /> OVERALL
            </div>
            <div className="text-2xl font-bold text-green-500">
              {totalLessons + totalChallenges > 0
                ? Math.round(((completedLessons + capturedFlags) / (totalLessons + totalChallenges)) * 100)
                : 0}% COMPLETE
            </div>
            {(totalLessons + totalChallenges) > 0 && (
              <div className="mt-2 h-1.5 bg-muted rounded-full overflow-hidden">
                <div className="h-full bg-green-500 rounded-full transition-all" style={{ width: `${((completedLessons + capturedFlags) / (totalLessons + totalChallenges)) * 100}%` }} />
              </div>
            )}
          </div>
        </div>
      </section>

      {/* CTA */}
      <section className="py-12 md:py-16 text-center">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          className="max-w-2xl mx-auto"
        >
          <h2 className="text-3xl font-bold mb-4">Choose Your Path</h2>
          <p className="text-muted-foreground mb-8">
            Each learning path is a focused curriculum combining theory modules with hands-on CTF challenges.
          </p>
          <Link href="/learn">
            <Button size="lg" variant="secondary">
              View All Learning Paths
              <ArrowRight className="w-4 h-4 ml-2" />
            </Button>
          </Link>
        </motion.div>
      </section>
    </Layout>
  );
}
